input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://brickschema.org/schema/1.2/brick#>
SELECT ?point WHERE {
  ?point a brick:ElectricityMeter .
} LIMIT 50

SELECT ?point ?class ?tsid ?label WHERE {
  ?point a ?class .
  FILTER (STRCONTAINS(STR(?class), "Meter"))
  OPTIONAL { ?point ref:hasLabel ?label . }
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
} LIMIT 100

SELECT ?point ?class ?tsid WHERE {
  ?point a ?class .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
} LIMIT 200
